import { Prisma, ProgramStatus, PurchaseStatus } from "@prisma/client";

import { prisma } from "@/lib/prisma";
import {
  prepareTemplateFirstProgramForUser,
  provisionProgramForPaidPurchase,
} from "@/lib/program/provisioning-service";

const totalProgramDays = 14;

export interface CurrentProgramEntry {
  programId: string;
  templateVersion: string;
  status: ProgramStatus;
  currentDay: number;
  totalDays: number;
  currentProgramDay: {
    dayIndex: number;
    stage: string;
    estimatedMinutes: number;
    title: string;
    focus: string;
    summary: string;
    completedAt: Date | null;
    completionPercent: number;
  };
}

export type CurrentProgramState =
  | { status: "ready"; program: CurrentProgramEntry }
  | { status: "missing_program_recovered"; program: CurrentProgramEntry }
  | { status: "no_purchase" }
  | { status: "missing_profile"; purchaseId: string }
  | {
      status: "missing_day_content";
      programId: string;
      currentDay: number;
    };

interface ContentSummary {
  title: string;
  focus: string;
  summary: string;
}

function clampDayIndex(dayIndex: number) {
  return Math.min(Math.max(dayIndex, 1), totalProgramDays);
}

function readContentSummary(contentJson: Prisma.JsonValue | null): ContentSummary {
  if (!contentJson || typeof contentJson !== "object" || Array.isArray(contentJson)) {
    return { title: "", focus: "", summary: "" };
  }

  const record = contentJson as Record<string, unknown>;

  return {
    title: typeof record.title === "string" ? record.title : "",
    focus: typeof record.focus === "string" ? record.focus : "",
    summary: typeof record.summary === "string" ? record.summary : "",
  };
}

function isContentJsonComplete(contentJson: Prisma.JsonValue | null) {
  const summary = readContentSummary(contentJson);
  return summary.title.length > 0 && summary.focus.length > 0;
}

async function loadActiveProgramEntry(userId: string): Promise<CurrentProgramEntry | null> {
  const program = await prisma.program.findFirst({
    where: {
      userId,
      status: ProgramStatus.ACTIVE,
      purchase: {
        status: PurchaseStatus.PAID,
      },
    },
    orderBy: {
      createdAt: "desc",
    },
    select: {
      id: true,
      templateVersion: true,
      status: true,
      currentDay: true,
    },
  });

  if (!program) {
    return null;
  }

  const currentDayIndex = clampDayIndex(program.currentDay);
  const currentProgramDay = await prisma.programDay.findUnique({
    where: {
      programId_dayIndex: {
        programId: program.id,
        dayIndex: currentDayIndex,
      },
    },
    select: {
      dayIndex: true,
      stage: true,
      estimatedMinutes: true,
      contentJson: true,
      completedAt: true,
      completionPercent: true,
    },
  });

  if (!currentProgramDay) {
    return null;
  }

  const summary = readContentSummary(currentProgramDay.contentJson);

  return {
    programId: program.id,
    templateVersion: program.templateVersion,
    status: program.status,
    currentDay: currentDayIndex,
    totalDays: totalProgramDays,
    currentProgramDay: {
      dayIndex: currentProgramDay.dayIndex,
      stage: currentProgramDay.stage,
      estimatedMinutes: currentProgramDay.estimatedMinutes,
      title: summary.title,
      focus: summary.focus,
      summary: summary.summary,
      completedAt: currentProgramDay.completedAt,
      completionPercent: currentProgramDay.completionPercent,
    },
  };
}

interface PaidPurchaseWithoutProgram {
  purchaseId: string;
}

async function findLatestPaidPurchaseWithoutActiveProgram(
  userId: string
): Promise<PaidPurchaseWithoutProgram | null> {
  const purchase = await prisma.purchase.findFirst({
    where: {
      userId,
      status: PurchaseStatus.PAID,
      OR: [
        { program: { is: null } },
        { program: { is: { status: { not: ProgramStatus.ACTIVE } } } },
      ],
    },
    orderBy: {
      createdAt: "desc",
    },
    select: {
      id: true,
    },
  });

  return purchase ? { purchaseId: purchase.id } : null;
}

async function attemptMissingProgramRecovery(
  userId: string,
  purchaseId: string
): Promise<CurrentProgramEntry | null> {
  const preparedProgram = await prepareTemplateFirstProgramForUser(userId);

  if (!preparedProgram) {
    return null;
  }

  await prisma.$transaction(
    async (tx) => {
      await provisionProgramForPaidPurchase(tx, {
        userId,
        purchaseId,
        preparedProgram,
      });
    },
    { timeout: 30000 }
  );

  return loadActiveProgramEntry(userId);
}

export async function resolveCurrentProgramForUser(
  userId: string
): Promise<CurrentProgramState> {
  const activeProgram = await loadActiveProgramEntry(userId);

  if (activeProgram) {
    if (!isContentJsonComplete(activeProgram.currentProgramDay.title ? {
      title: activeProgram.currentProgramDay.title,
      focus: activeProgram.currentProgramDay.focus,
    } : null)) {
      return {
        status: "missing_day_content",
        programId: activeProgram.programId,
        currentDay: activeProgram.currentDay,
      };
    }

    return { status: "ready", program: activeProgram };
  }

  const paidPurchaseWithoutProgram =
    await findLatestPaidPurchaseWithoutActiveProgram(userId);

  if (!paidPurchaseWithoutProgram) {
    return { status: "no_purchase" };
  }

  const recoveryProfile = await prisma.recoveryProfile.findUnique({
    where: { userId },
    select: { id: true },
  });

  if (!recoveryProfile) {
    return {
      status: "missing_profile",
      purchaseId: paidPurchaseWithoutProgram.purchaseId,
    };
  }

  const recoveredProgram = await attemptMissingProgramRecovery(
    userId,
    paidPurchaseWithoutProgram.purchaseId
  );

  if (!recoveredProgram) {
    return {
      status: "missing_profile",
      purchaseId: paidPurchaseWithoutProgram.purchaseId,
    };
  }

  return { status: "missing_program_recovered", program: recoveredProgram };
}

import { Prisma, ProgramStatus, PurchaseStatus } from "@prisma/client";

import { prisma } from "@/lib/prisma";
import {
  prepareTemplateFirstProgramForUser,
  provisionProgramForPaidPurchase,
} from "@/lib/program/provisioning-service";

const totalProgramDays = 14;

export interface CurrentProgramEntry {
  programId: string;
  templateVersion: string;
  status: ProgramStatus;
  currentDay: number;
  totalDays: number;
  currentProgramDay: {
    dayIndex: number;
    stage: string;
    estimatedMinutes: number;
    title: string;
    focus: string;
    summary: string;
    completedAt: Date | null;
    completionPercent: number;
  };
}

export type CurrentProgramState =
  | { status: "ready"; program: CurrentProgramEntry }
  | { status: "missing_program_recovered"; program: CurrentProgramEntry }
  | { status: "no_purchase" }
  | { status: "missing_profile"; purchaseId: string }
  | {
      status: "missing_day_content";
      programId: string;
      currentDay: number;
    };

interface ContentSummary {
  title: string;
  focus: string;
  summary: string;
}

function clampDayIndex(dayIndex: number) {
  return Math.min(Math.max(dayIndex, 1), totalProgramDays);
}

function readContentSummary(contentJson: Prisma.JsonValue | null): ContentSummary {
  if (!contentJson || typeof contentJson !== "object" || Array.isArray(contentJson)) {
    return { title: "", focus: "", summary: "" };
  }

  const record = contentJson as Record<string, unknown>;

  return {
    title: typeof record.title === "string" ? record.title : "",
    focus: typeof record.focus === "string" ? record.focus : "",
    summary: typeof record.summary === "string" ? record.summary : "",
  };
}

interface LoadedActiveProgram {
  entry: CurrentProgramEntry;
  contentComplete: boolean;
}

async function loadActiveProgramEntry(
  userId: string
): Promise<LoadedActiveProgram | null> {
  const program = await prisma.program.findFirst({
    where: {
      userId,
      status: ProgramStatus.ACTIVE,
      purchase: {
        status: PurchaseStatus.PAID,
      },
    },
    orderBy: {
      createdAt: "desc",
    },
    select: {
      id: true,
      templateVersion: true,
      status: true,
      currentDay: true,
    },
  });

  if (!program) {
    return null;
  }

  const currentDayIndex = clampDayIndex(program.currentDay);
  const currentProgramDay = await prisma.programDay.findUnique({
    where: {
      programId_dayIndex: {
        programId: program.id,
        dayIndex: currentDayIndex,
      },
    },
    select: {
      dayIndex: true,
      stage: true,
      estimatedMinutes: true,
      contentJson: true,
      completedAt: true,
      completionPercent: true,
    },
  });

  if (!currentProgramDay) {
    return null;
  }

  const summary = readContentSummary(currentProgramDay.contentJson);
  const contentComplete = summary.title.length > 0 && summary.focus.length > 0;

  return {
    entry: {
      programId: program.id,
      templateVersion: program.templateVersion,
      status: program.status,
      currentDay: currentDayIndex,
      totalDays: totalProgramDays,
      currentProgramDay: {
        dayIndex: currentProgramDay.dayIndex,
        stage: currentProgramDay.stage,
        estimatedMinutes: currentProgramDay.estimatedMinutes,
        title: summary.title,
        focus: summary.focus,
        summary: summary.summary,
        completedAt: currentProgramDay.completedAt,
        completionPercent: currentProgramDay.completionPercent,
      },
    },
    contentComplete,
  };
}

async function findLatestPaidPurchaseWithoutActiveProgram(
  userId: string
): Promise<{ purchaseId: string } | null> {
  const purchase = await prisma.purchase.findFirst({
    where: {
      userId,
      status: PurchaseStatus.PAID,
      OR: [
        { program: { is: null } },
        { program: { is: { status: { not: ProgramStatus.ACTIVE } } } },
      ],
    },
    orderBy: {
      createdAt: "desc",
    },
    select: { id: true },
  });

  return purchase ? { purchaseId: purchase.id } : null;
}

async function attemptMissingProgramRecovery(
  userId: string,
  purchaseId: string
): Promise<CurrentProgramEntry | null> {
  const preparedProgram = await prepareTemplateFirstProgramForUser(userId);

  if (!preparedProgram) {
    return null;
  }

  await prisma.$transaction(
    async (tx) => {
      await provisionProgramForPaidPurchase(tx, {
        userId,
        purchaseId,
        preparedProgram,
      });
    },
    { timeout: 30000 }
  );

  const reloaded = await loadActiveProgramEntry(userId);
  return reloaded?.entry ?? null;
}

export async function resolveCurrentProgramForUser(
  userId: string
): Promise<CurrentProgramState> {
  const activeProgram = await loadActiveProgramEntry(userId);

  if (activeProgram) {
    if (!activeProgram.contentComplete) {
      return {
        status: "missing_day_content",
        programId: activeProgram.entry.programId,
        currentDay: activeProgram.entry.currentDay,
      };
    }

    return { status: "ready", program: activeProgram.entry };
  }

  const paidPurchaseWithoutProgram =
    await findLatestPaidPurchaseWithoutActiveProgram(userId);

  if (!paidPurchaseWithoutProgram) {
    return { status: "no_purchase" };
  }

  const recoveryProfile = await prisma.recoveryProfile.findUnique({
    where: { userId },
    select: { id: true },
  });

  if (!recoveryProfile) {
    return {
      status: "missing_profile",
      purchaseId: paidPurchaseWithoutProgram.purchaseId,
    };
  }

  const recoveredProgram = await attemptMissingProgramRecovery(
    userId,
    paidPurchaseWithoutProgram.purchaseId
  );

  if (!recoveredProgram) {
    return {
      status: "missing_profile",
      purchaseId: paidPurchaseWithoutProgram.purchaseId,
    };
  }

  return { status: "missing_program_recovered", program: recoveredProgram };
}

import { NextResponse } from "next/server";

import { getAuthSession } from "@/lib/auth/session";
import { resolveCurrentProgramForUser } from "@/lib/program/current-program-service";

export const dynamic = "force-dynamic";

export async function GET() {
  const session = await getAuthSession();

  if (!session?.user?.id) {
    return NextResponse.json({ error: "unauthenticated" }, { status: 401 });
  }

  try {
    const state = await resolveCurrentProgramForUser(session.user.id);

    if (state.status === "ready" || state.status === "missing_program_recovered") {
      return NextResponse.json({
        status: state.status,
        program: state.program,
      });
    }

    if (state.status === "missing_profile") {
      return NextResponse.json(
        {
          status: state.status,
          redirectTo: "/onboarding",
        },
        { status: 200 }
      );
    }

    if (state.status === "missing_day_content") {
      return NextResponse.json(
        {
          status: state.status,
          programId: state.programId,
          currentDay: state.currentDay,
          redirectTo: "/onboarding",
        },
        { status: 200 }
      );
    }

    return NextResponse.json(
      {
        status: "no_purchase",
        redirectTo: "/onboarding",
      },
      { status: 200 }
    );
  } catch (error) {
    console.error("Failed to resolve current program", {
      userId: session.user.id,
      error,
    });

    return NextResponse.json(
      { error: "current_program_unavailable" },
      { status: 500 }
    );
  }
}

